cells.source:
results = pd.DataFrame(
    {
        "relationship": [
            "Unadjusted",
            "Controlling for\nrating volume",
        ],
        "correlation": [
            overall_r,
            partial_r,
        ],
    }
)


fig, ax = plt.subplots(
    figsize=(7, 5)
)

bars = ax.bar(
    results["relationship"],
    results["correlation"],
)

ax.axhline(
    0,
    linewidth=1,
)

ax.set_title(
    "Price and Positive Review Ratio"
)

ax.set_ylabel(
    "Pearson Correlation"
)


for bar, value in zip(
    bars,
    results["correlation"],
):
    ax.text(
        bar.get_x() + bar.get_width() / 2,
        value,
        f"{value:.3f}",
        ha="center",
        va="bottom",
    )


plt.tight_layout()
plt.show()

